// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Path;
import java.util.List;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A pinned Frontier lease must describe the LMDB snapshot the planner reads. The store makes a commit visible before it
 * records the commit's coordinates with the statistics service, so a snapshot newer than every recorded commit can
 * contain rows that no generation or mutation tail describes. Such a snapshot must get a typed fallback, never a READY
 * lease on the older generation.
 */
class LmdbStatisticsSnapshotCoverageTest {

	private static final long PREDICATE = 22L;

	@TempDir
	Path directory;

	private LmdbStatisticsService service;

	@AfterEach
	void closeService() {
		if (service != null) {
			service.close();
		}
	}

	@Test
	void snapshotNewerThanEveryRecordedCommitIsNotServedFromAnOlderGeneration() throws Exception {
		service = openService();
		service.publish(generation(1L, 5L));
		service.recordStoreCommit(5L, 5L, System.currentTimeMillis());

		// LMDB has committed epoch 6 (it may hold new statements), but recordStoreCommit(6, ...) has not run yet.
		try (FrontierStatisticsLease lease = service.acquire(6L)) {
			assertFalse(lease.ready(),
					"a snapshot newer than every recorded commit must not be served from the epoch-5 generation");
			assertEquals(FrontierFallbackReason.GENERATION_TOO_STALE, lease.fallbackReason());
		}
		try (FrontierStatisticsView view = service.openView(6L)) {
			assertFalse(view.ready(), "a pinned planner view must decline the unrecorded snapshot");
		}
		FrontierLeafProbe probe = predicateProbe();
		assertNotEquals(FrontierFallbackReason.NONE, service.estimateLeaf(6L, probe).fallbackReason());
		assertNotEquals(FrontierFallbackReason.NONE,
				service.estimateJoin(6L, new FrontierJoinProbe(probe, 0, probe, 0)).fallbackReason());
		assertTrue(Double.isNaN(service.estimateProjectedDistinct(6L, probe, 0)));

		try (FrontierStatisticsLease lease = service.acquire(5L)) {
			assertTrue(lease.ready(), "the recorded, covered snapshot stays servable");
		}
	}

	@Test
	void recordedCommitMakesTheNewerSnapshotQueryableThroughTheMutationTail() throws Exception {
		service = openService();
		service.publish(generation(1L, 5L));
		service.recordStoreCommit(5L, 5L, System.currentTimeMillis());
		assertFalse(service.acquire(6L).ready());

		service.recordStoreCommit(6L, 6L, System.currentTimeMillis());
		service.installMutationTail(List.of(new FrontierMutation(6L, 6L, true, true, 106L, PREDICATE, 206L, 0L)));

		FrontierLeafEstimate estimate = service.estimateLeaf(6L, predicateProbe());
		assertEquals(FrontierFallbackReason.NONE, estimate.fallbackReason(),
				"once the commit is recorded with its tail, the newer snapshot is covered exactly");
		assertEquals(1.0d, estimate.pointRows(), 0.0d);
		try (FrontierStatisticsLease lease = service.acquire(5L)) {
			assertTrue(lease.ready());
		}
		try (FrontierStatisticsLease lease = service.acquire(6L)) {
			assertFalse(lease.ready(), "the generation alone still does not describe the statement commit at 6");
		}
	}

	@Test
	void metadataOnlyEpochAdvanceIsServedOnceItIsRecorded() throws Exception {
		service = openService();
		service.publish(generation(1L, 5L));
		service.recordStoreCommit(5L, 5L, System.currentTimeMillis());

		// A journal acknowledgement committed epoch 6 without statement changes; it is recorded after its commit.
		assertFalse(service.acquire(6L).ready(), "before it is recorded, epoch 6 could be a statement commit");
		assertTrue(service.recordMetadataOnlySnapshotAdvance(6L, 5L));
		try (FrontierStatisticsLease lease = service.acquire(6L)) {
			assertTrue(lease.ready(), "a recorded metadata-only advance keeps the covering generation servable");
		}
		assertFalse(service.acquire(7L).ready());
	}

	@Test
	void generationBuiltFromAnUnrecordedSnapshotCoversItsOwnEpoch() throws Exception {
		service = openService();
		service.recordStoreCommit(5L, 5L, System.currentTimeMillis());
		// The builder pinned epoch 6 after LMDB committed it but before the store recorded it.
		service.publish(generation(1L, 6L));

		try (FrontierStatisticsLease lease = service.acquire(6L)) {
			assertTrue(lease.ready(), "a generation built from snapshot 6 describes snapshot 6 exactly");
		}
		assertFalse(service.acquire(7L).ready());
	}

	@Test
	void serviceWithoutRecordedCommitsKeepsItsCoveredEpochsQueryable() throws Exception {
		service = openService();
		service.publish(generation(1L, 5L));

		try (FrontierStatisticsLease lease = service.acquire(5L)) {
			assertTrue(lease.ready());
		}
		assertEquals(FrontierFallbackReason.GENERATION_TOO_STALE, service.acquire(6L).fallbackReason());
		assertEquals(FrontierFallbackReason.NONE, service.estimateLeaf(5L, predicateProbe()).fallbackReason());
	}

	private LmdbStatisticsService openService() throws IOException {
		return LmdbStatisticsService.open(directory,
				new FrontierStatisticsHeapGovernor(
						2L * 1024L * 1024L * 1024L,
						256L * 1024L * 1024L,
						512L * 1024L * 1024L,
						256L * 1024L * 1024L),
				128L * 1024L * 1024L * 1024L,
				60_000L);
	}

	private FrontierStatisticsManifest generation(long generationId, long epoch) throws IOException {
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);
		return FrontierStatisticsBuilder.build(directory, generationId, -1L, emptySnapshot(epoch), governor,
				config);
	}

	private static FrontierLeafProbe predicateProbe() {
		return new FrontierLeafProbe(FrontierLeafProbe.EXPLICIT,
				FrontierLeafProbe.PREDICATE | FrontierLeafProbe.CONTEXT, 0L, PREDICATE, 0L, 0L);
	}

	private static FrontierSnapshotSource emptySnapshot(long epoch) {
		return new FrontierSnapshotSource() {
			@Override
			public long snapshotEpoch() {
				return epoch;
			}

			@Override
			public long rowCount(boolean explicit) {
				return 0L;
			}

			@Override
			public long scan(boolean explicit, RawQuadSink sink) {
				return 0L;
			}

			@Override
			public boolean contains(long subjectId, long predicateId, long objectId, long contextId,
					boolean explicit) {
				return false;
			}

			@Override
			public void close() {
			}
		};
	}
}
